WITH cleaned AS (SELECT id, event_type, page, event_time, duration_sec, COALESCE(duration_sec, 0) AS duration_sec_filled, CONCAT(event_type, ' - ', page) AS event_type_page FROM web_events WHERE event_time >= TO_DATE('2023-08-29') AND page IS NOT NULL), deduped AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY page, event_type ORDER BY duration_sec NULLS FIRST, id) AS dedup_rank FROM cleaned) x WHERE dedup_rank = 1), with_windows AS (SELECT *, NTILE(3) OVER (PARTITION BY page ORDER BY duration_sec_filled, id) AS duration_sec_filled_bucket, STDDEV_SAMP(duration_sec_filled) OVER (PARTITION BY event_type, page) AS event_type_stddev_samp_duration_sec_filled FROM deduped), filtered AS (SELECT id, event_type, page, event_time, duration_sec, duration_sec_filled, event_type_page, dedup_rank, duration_sec_filled_bucket, event_type_stddev_samp_duration_sec_filled, COALESCE(duration_sec_filled, 0) AS duration_sec_filled_filled, COALESCE(page, 'NONE') AS page_clean FROM with_windows WHERE page IS NOT NULL) SELECT page, DATE_TRUNC('YEAR', event_time) AS year_start, (UNIX_TIMESTAMP(MAX(event_time)) - UNIX_TIMESTAMP(MIN(event_time))) / 60 AS span_minutes, COUNT(CASE WHEN page = '/cart' THEN 1 END) AS cart_count, SUM(duration_sec_filled) AS total_duration_sec_filled FROM filtered GROUP BY page, year_start HAVING SUM(duration_sec_filled) > 0;
